START TRANSACTION;
UPDATE div_signals SET signal_number = CASE id WHEN 3037 THEN 'CHOK S-17' WHEN 3038 THEN 'CHOK S-12' WHEN 3039 THEN 'CHOK S-13' WHEN 3040 THEN 'CHOK S-14' WHEN 3041 THEN 'CHOK S-11'
  WHEN 3043 THEN 'PYJE S-17' WHEN 3044 THEN 'PYJE S-12' WHEN 3045 THEN 'PYJE S-13' WHEN 3046 THEN 'PYJE S-14' WHEN 3047 THEN 'PYJE S-11' END WHERE id IN (3037,3038,3039,3040,3041,3043,3044,3045,3046,3047);
UPDATE div_signals SET normalized_signal_number = REPLACE(REPLACE(signal_number,' ',''),'-','') WHERE id IN (3037,3038,3039,3040,3041,3043,3044,3045,3046,3047);
UPDATE div_signal_book_rows r JOIN div_signals s ON s.id = r.signal_id SET r.display_signal_no = s.signal_number WHERE s.id IN (3037,3038,3039,3040,3041,3043,3044,3045,3046,3047);
UPDATE div_signals SET has_calling_on = 0 WHERE id IN (3037,3043,3017,3023);
UPDATE div_signal_aliases SET signal_id = CASE normalized_alias WHEN 'CHOKS11' THEN 3041 WHEN 'CHOKS12' THEN 3038 WHEN 'CHOKS13' THEN 3039
  WHEN 'PYJES11' THEN 3047 WHEN 'PYJES12' THEN 3044 WHEN 'PYJES13' THEN 3045 END
 WHERE normalized_alias IN ('CHOKS11','CHOKS12','CHOKS13','PYJES11','PYJES12','PYJES13');
DELETE FROM div_signal_aliases WHERE normalized_alias IN ('CHOKS50','CHOKS46','CHOKS45','CHOKS47','CHOKS42','PYJES50','PYJES46','PYJES45','PYJES47','PYJES42');
DELETE FROM div_signal_history WHERE remarks = 'Caution Order 12.08.2026 (MRVC Panvel-Karjat)';
